    def ca_auth():
        """生成 OAuth 授权 URL：先尝试自动拉起浏览器，失败则复制到剪贴板兜底"""
        import urllib.request
        import webbrowser
        # 取服务端口（运行中优先用实际端口，否则用输入框）
        port = None
        if services["ca"].running:
            try:
                port = ca_port.get().strip() if ca_port.get().strip().isdigit() else "9100"
                with urllib.request.urlopen(f"http://127.0.0.1:{port}/v1/auth/url", timeout=8) as r:
                    d = json.loads(r.read().decode("utf-8"))
                url = (d.get("data") or {}).get("url", "")
                if url:
                    try:
                        if webbrowser.open(url, new=2):
                            emit("[ca] 已拉起浏览器：在其中登录授权，完成后点“测试”验证")
                            return
                    except Exception:
                        pass
                    root.clipboard_clear()
                    root.clipboard_append(url)
                    emit("[ca] 浏览器拉起失败，授权 URL 已复制到剪贴板：手动打开并登录，完成后点“测试”验证")
                    return
            except Exception as e:  # noqa: BLE001
                emit(f"[ca] 获取授权 URL 失败（服务未运行？）：{e}")
                return
        emit("[ca] 请先启动服务，再点“授权”")

    def refresh_ca_info():
        """ca_info 显示：余额 + 授权状态"""
        try:
            if not services["ca"].running:
                ca_info.configure(text="每日 10M token（3 个免费模型共用）· 首次点“授权”在浏览器登录一次，此后自动续期",
                                  foreground="#555")
                return
            import urllib.request
            port = ca_port.get().strip() if ca_port.get().strip().isdigit() else "9100"
            base = f"http://127.0.0.1:{port}"
            with urllib.request.urlopen(base + "/v1/balance", timeout=15) as r:
                b = json.loads(r.read().decode("utf-8"))
            if b.get("ok"):
                w = b.get("data") or {}
                line = (f"剩余额度 {w.get('total_balance', 0):,} / {w.get('total_quota', 0):,} tokens "
                        f"(已用 {w.get('used_amount', 0):,})")
            else:
                line = "余额查询失败（可能需重新授权）"
            try:
                with urllib.request.urlopen(base + "/v1/auth/status", timeout=8) as r:
                    st = json.loads(r.read().decode("utf-8"))
                auth = "授权有效" if st.get("ok") else f"未授权：{st.get('error', '')[:40]}"
            except Exception:
                auth = "授权状态未知"
            ca_info.configure(text=f"{line}\n{auth}", foreground="#1a7f37")
        except Exception:
            pass

    def _http_test(key, url, fmt):
        import urllib.request
        try:
            with urllib.request.urlopen(url, timeout=5) as r:
                data = json.loads(r.read().decode("utf-8"))
            emit(f"[{key}] 测试 {url} → {fmt(data)}")
        except Exception as e:  # noqa: BLE001
            emit(f"[{key}] 测试 {url} 失败：{e}")

    def _http_test_chat(key, url):
        import urllib.request
        model = (eff_models(key) or ["auto"])[0]
        # WorkBuddy 上游要求首条为 system prompt，否则 400（code 11128）
        msgs = ([{"role": "system", "content": "you are a helpful assistant"}]
                if key == "cb" else []) + [{"role": "user", "content": "hi"}]
        payload = json.dumps({"model": model, "messages": msgs, "max_tokens": 60, "stream": False}).encode("utf-8")
        req = urllib.request.Request(url, data=payload, headers={"Content-Type": "application/json"}, method="POST")
        try:
            with urllib.request.urlopen(req, timeout=60) as r:
                data = json.loads(r.read().decode("utf-8"))
            choices = (data or {}).get("choices") or []
            m = choices[0].get("message", {}) if choices else {}
            msg = m.get("content") or ""
            if not msg and m.get("reasoning_content"):
                msg = "[reasoning] " + str(m.get("reasoning_content"))[:40]
            if not msg:
                msg = "finish=" + str(choices[0].get("finish_reason", "?")) if choices else "no choices"
            emit(f"[{key}] 测试 {url} → chat OK({model}) · {msg[:60]}")
        except Exception as e:  # noqa: BLE001
            emit(f"[{key}] 测试 {url} 失败：{e}")

    def detect_env():
        emit("──── 本地环境检测 ────")
        for key, skey, name in (("cb", "wb_path", "WorkBuddyAI"),
                                ("mc", "mc_path", "MonkeyCode"),
                                ("ca", "ca_path", "CodeArts"),
                                ("rc", "rc_path", "商汤小浣熊"),
                                ("cp", "cp_path", "CatPaw")):
            entry = {"cb": cb_path, "mc": mc_path, "rc": rc_path, "cp": cp_path}.get(key, ca_path)
            cur = entry.get().strip()
            if not cur:
                found = find_install({"cb": "wb", "mc": "mc", "rc": "rc", "cp": "cp"}.get(key, "ca"))
                if found:
                    settings[skey] = found
                    save_settings(settings)
                    set_install_path(key, found)
                    cur = found
            ok = bool(cur) and Path(cur).exists()
            emit(f"{name} 程序位置: {'✓ ' + cur if ok else '✗ 未找到（可点「浏览…」指定 exe 或文件夹）'}")
        # Raccoon auth check
        rc_auth_dir = rc_auth.get().strip() or str(Path.home() / ".box-agent" / "config")
        rc_auth_file = Path(rc_auth_dir) / "auth.json"
        rc_ok = rc_auth_file.is_file()
        emit(f"Raccoon 凭据:     {'✓ ' + str(rc_auth_file) if rc_ok else '✗ 未找到 auth.json（请先用桌面端登录一次）'}")
        # Raccoon auth check
        rc_auth_dir = rc_auth.get().strip() or str(Path.home() / ".box-agent" / "config")
        rc_auth_file = Path(rc_auth_dir) / "auth.json"
        rc_ok = rc_auth_file.is_file()
        emit(f"Raccoon 凭据:     {'✓ ' + str(rc_auth_file) if rc_ok else '✗ 未找到 auth.json（请先用桌面端登录一次）'}")
        s = read_cb_summary()
        _ui_cb_info(s)
        if s.get("found") and "error" not in s:
            emit(f"CodeBuddy 凭据:   ✓ {s['nickname']} / {s['enterprise']} · "
                 f"{'token 已过期(将自动刷新)' if s['expired'] else 'token 有效'} · 域 {s['domain']}")
        elif s.get("found"):
            emit(f"CodeBuddy 凭据:   读取失败 {s.get('error')}")
        else:
            emit("CodeBuddy 凭据:   ✗ 未找到（请先登录 WorkBuddy/CodeBuddy 桌面端）")
        emit(f"Python 依赖:      {'✓ 齐全' if not missing_deps() else '✗ 缺失: ' + ' '.join(missing_deps())}")
        mc_base = monkeycode_upstream_base()
        emit(f"MonkeyCode 上游: {'✓ ' + mc_base if mc_base else '✗ 未找到（config.json 无 models[0].api_key）'}")
        ui(refresh_mc_info)
        emit("────────────────────")

    def refresh_cb_credits():
        """cb_info 追加第3行剩余额度（仅服务运行时查询）"""
        try:
            if not services["cb"].running:
                return
            import urllib.request
            base = cb_url.get().rstrip("/")
            with urllib.request.urlopen(base + "/credits", timeout=15) as r:
                d = json.loads(r.read().decode("utf-8"))
            line = (f"剩余额度 {d.get('remain', 0):.2f} credits "
                    f"(总数 {d.get('total', 0):.0f} · 已用 {d.get('used', 0):.2f})")
            cur = cb_info.cget("text")
            lines = [l for l in cur.split("\n") if not l.startswith("剩余额度")]
            cb_info.configure(text="\n".join(lines + [line]))
        except Exception:
            pass

    def _ui_cb_info(s: dict):
        def apply():
            if not s.get("found"):
                cb_info.configure(text="✗ 未找到 CodeBuddy/WorkBuddy 登录凭据 —— 请先打开 WorkBuddyAI 完成登录",
                                  foreground="#c0392b")
                return
            if "error" in s:
                cb_info.configure(text=f"凭据文件异常：{s['error']}", foreground="#c0392b")
                return
            exp = time.strftime("%Y-%m-%d %H:%M", time.localtime(s["expires_at"] / 1000)) if s.get("expires_at") else "?"
            cb_info.configure(
                text=f"✓ 账号 {s['nickname']}（{s['enterprise']}）· 域 {s['domain']} · token {'已过期,将自动刷新' if s['expired'] else f'有效至 {exp}'}\n"
                     f"  凭据文件：{s['path']}",
                foreground="#1a7f37")
        ui(apply)

    def _ui_status(key, kind, text):
        def apply():
            color = {"run": "#1a7f37", "error": "#c0392b", "off": "#999"}.get(kind, "#999")
            mapping = {"cb": (cb_status, cb_led), "mc": (mc_status, mc_led), "ca": (ca_status, ca_led), "rc": (rc_status, rc_led), "cp": (cp_status, cp_led)}
            lab, led = mapping.get(key, (cb_status, cb_led))
            lab.configure(text=text, foreground=color)
            led.itemconfigure("o",
                fill={"run": "#22c55e", "error": "#ef4444", "off": "#9ca3af"}.get(kind, "#999"))
            running = any(s.running for s in services.values())
            global_status.configure(foreground="#22c55e" if running else ("#ef4444" if any(
                s.error for s in services.values()) else "#9ca3af"))
        ui(apply)

    # ---------------- 队列泵 & LED 轮询 ----------------
    def pump():
        try:
            while True:
                kind, payload = log_q.get_nowait()
                if kind == "log":
                    log_text.configure(state="normal")
                    log_text.insert("end", payload + "\n", log_line_tag(payload))
                    if int(log_text.index("end-1c").split(".")[0]) > 3000:
                        log_text.delete("1.0", "200.0")
                    log_text.see("end")
                    log_text.configure(state="disabled")
                elif kind == "call":
                    fn, args = payload
                    try:
                        fn(*args)
                    except Exception as e:  # noqa: BLE001
                        print(f"[ui-error] {e}")
        except queue.Empty:
            pass
        root.after(120, pump)

    def poll_status():
        for key, svc in services.items():
            if svc.running:
                el = int(time.time() - (svc.started_at or time.time()))
                _ui_status(key, "run", f"运行中 · {el}s")
            elif svc.error:
                _ui_status(key, "error", f"异常：{svc.error[:60]}")
            else:
                _ui_status(key, "off", "未启动")
        root.after(800, poll_status)

    _exiting = False

    def real_exit():
        nonlocal _exiting
        if _exiting:
            return
        _exiting = True
        _persist()
        emit("正在退出 …")
        for svc in services.values():
            try:
                svc.stop(6)
            except Exception:
                pass
        try:
            if tray_icon is not None:
                tray_icon.stop()
        except Exception:
            pass
        if smoke:
            print("UISMOKE OK")
        root.destroy()

    def on_close():
        # 右上角 ×：有托盘则缩小到托盘（服务继续运行），否则真正退出
        if tray_icon is not None:
            root.withdraw()
            emit("已最小化到系统托盘，服务继续运行（退出请用托盘右键菜单 → 退出）")
        else:
            real_exit()

    root.protocol("WM_DELETE_WINDOW", on_close)

    _last_refresh = [0.0]

    def _schedule_refresh(delay: float = 10.0):
        """延迟后台刷新模型存活（去重：120 秒内只跑一次）。"""
        if time.time() - _last_refresh[0] < 120:
            return
        _last_refresh[0] = time.time()

        def _run():
            time.sleep(delay)
            try:
                bases = {}
                for k, ent, dflt in (("mc", mc_port, 9000), ("ca", ca_port, 9100), ("cp", cp_port, 9300)):
                    try:
                        p = int(ent.get())
                    except ValueError:
                        p = dflt
                    if services.get(k) and services[k].running:
                        bases[k] = f"http://127.0.0.1:{p}/v1"
                refresh_models_startup(settings, emit, bases)
            except Exception as e:  # noqa: BLE001
                emit(f"[models] 启动刷新失败：{e}")
        threading.Thread(target=_run, daemon=True).start()

    # ---------------- 启动初始化（后台） ----------------
    def init_bg():
        try:
            refresh_model_hints()
            materialize(emit)
            detect_env()
            _validate_models()
            create_tray()
            if autostart_var.get() and not smoke:
                emit("[auto] 已开启自动启动 …")
                start_all()
            _schedule_refresh()
        except Exception as e:  # noqa: BLE001
            emit(f"[init] 初始化失败：{type(e).__name__}: {e}")

    threading.Thread(target=init_bg, daemon=True).start()
    pump()
    poll_status()
    _refresh_urls()
    refresh_hermes_status()
    if smoke:
        # 自检模式：不显示窗口，构建完成后自动退出（验证 UI 可正常构建）
        root.withdraw()
        root.after(4000, real_exit)
    root.mainloop()
    # mainloop 仅在 real_exit→root.destroy 后返回；强制结束进程，
    # 防止托盘/第三方线程残留导致控制台黑框不退
    if _exiting:
        os._exit(0)


